-- Seed one concise form cue per template exercise (en/es/el) — migration 0056
-- added the columns; this fills them for all 171 templates. Idempotent:
-- matching is by lower(name) on template rows, re-running just rewrites the
-- same values. Custom (user-created) exercises keep NULL cues.

UPDATE exercises e SET instructions = v.en, instructions_es = v.es, instructions_el = v.el
FROM (VALUES
  -- ── Chest ──
  ('bench press', 'Keep shoulder blades pinched, feet planted; lower the bar to mid-chest and press up in a slight arc.', 'Escápulas retraídas y pies firmes; baja la barra al pecho medio y empuja en un arco ligero.', 'Κράτα τις ωμοπλάτες σφιγμένες, πόδια σταθερά· κατέβασε την μπάρα στο μέσο του στήθους και πίεσε ψηλά.'),
  ('incline bench press', 'Set the bench 30-45°; lower to the upper chest and press without bouncing.', 'Banco a 30-45°; baja al pecho superior y empuja sin rebotar.', 'Πάγκος 30-45°· κατέβασε στο άνω στήθος και πίεσε χωρίς αναπήδηση.'),
  ('decline bench press', 'Lock your legs, lower the bar to the lower chest, and keep wrists stacked over elbows.', 'Asegura las piernas, baja la barra al pecho inferior y mantén muñecas sobre codos.', 'Κλείδωσε τα πόδια, κατέβασε στην κάτω πλευρά του στήθους, καρποί πάνω από αγκώνες.'),
  ('incline dumbbell press', 'Press the dumbbells up and slightly together; lower until you feel a chest stretch.', 'Empuja las mancuernas arriba y ligeramente juntas; baja hasta sentir estiramiento en el pecho.', 'Πίεσε τους αλτήρες ψηλά και ελαφρώς μαζί· κατέβασε μέχρι να νιώσεις διάταση στο στήθος.'),
  ('machine chest press', 'Adjust the seat so handles sit at mid-chest; press smoothly without locking elbows hard.', 'Ajusta el asiento con agarres al pecho medio; empuja suave sin bloquear codos.', 'Ρύθμισε το κάθισμα ώστε οι λαβές να είναι στο μέσο στήθος· πίεσε ομαλά χωρίς κλείδωμα αγκώνων.'),
  ('dumbbell flyes', 'Keep a soft elbow bend and open wide until a stretch, then squeeze the dumbbells together.', 'Codos semiflexionados; abre amplio hasta estirar y junta las mancuernas apretando el pecho.', 'Ελαφρώς λυγισμένοι αγκώνες· άνοιξε μέχρι διάταση και σφίξε τους αλτήρες μαζί.'),
  ('cable fly', 'Step forward, slight elbow bend, and bring the handles together in a hugging arc.', 'Da un paso al frente, codos semiflexionados, y junta los agarres en arco de abrazo.', 'Βήμα μπροστά, ελαφρώς λυγισμένοι αγκώνες, ένωσε τις λαβές σε τόξο αγκαλιάς.'),
  ('cable crossover', 'Cross the handles slightly at the bottom and control the return — no shoulder shrugging.', 'Cruza levemente los agarres abajo y controla el regreso — sin encoger hombros.', 'Σταύρωσε ελαφρά τις λαβές χαμηλά και έλεγξε την επιστροφή — χωρίς σήκωμα ώμων.'),
  ('pec deck', 'Sit tall with elbows level to shoulders; squeeze the pads together and resist the way back.', 'Siéntate erguido, codos a la altura de hombros; junta y resiste la vuelta.', 'Κάτσε όρθια με αγκώνες στο ύψος των ώμων· σφίξε τα μαξιλαράκια και αντιστάσου στην επιστροφή.'),
  ('dip', 'Lean slightly forward for chest emphasis; lower until shoulders reach elbow level.', 'Inclínate un poco adelante para el pecho; baja hasta que los hombros lleguen al nivel de los codos.', 'Γείρε ελαφρώς μπροστά για στήθος· κατέβα μέχρι οι ώμοι να φτάσουν στο ύψος των αγκώνων.'),
  ('chest dips', 'Flare elbows slightly and lean forward; press up without locking out abruptly.', 'Codos algo abiertos e inclinación adelante; sube sin bloquear de golpe.', 'Αγκώνες ελαφρώς ανοιχτοί και κλίση μπροστά· ανέβα χωρίς απότομο κλείδωμα.'),
  ('push-ups', 'Body in one line, hands under shoulders; lower chest to an inch from the floor.', 'Cuerpo en línea, manos bajo hombros; baja el pecho casi al suelo.', 'Σώμα σε ευθεία, χέρια κάτω από ώμους· κατέβασε το στήθος σχεδόν στο πάτωμα.'),
  ('dumbbell pullover', 'Keep hips down and arms near-straight; pull the dumbbell over in a wide arc.', 'Caderas abajo y brazos casi rectos; lleva la mancuerna en arco amplio.', 'Γοφοί χαμηλά, χέρια σχεδόν τεντωμένα· φέρε τον αλτήρα σε φαρδύ τόξο.'),
  ('landmine press', 'Press the bar up and slightly across; keep ribs down and glutes tight.', 'Empuja la barra arriba y algo cruzada; costillas abajo y glúteos firmes.', 'Πίεσε την μπάρα ψηλά και ελαφρώς διαγώνια· πλευρά μέσα, γλουτοί σφιχτοί.'),
  ('floor press', 'Pause the upper arms on the floor each rep, then drive the bar straight up.', 'Pausa los brazos en el suelo en cada repetición y empuja la barra recta.', 'Παύση με τους βραχίονες στο πάτωμα σε κάθε επανάληψη, μετά πίεσε ευθεία ψηλά.'),
  ('incline cable fly', 'Set pulleys low; sweep the handles up and in until they meet over the upper chest.', 'Poleas abajo; lleva los agarres arriba y adentro hasta unirlos sobre el pecho superior.', 'Τροχαλίες χαμηλά· φέρε τις λαβές ψηλά και μέσα πάνω από το άνω στήθος.'),
  ('smith machine bench press', 'Set your arch and bar path first — the rail is fixed, so position the bench precisely.', 'Fija tu arco y la trayectoria primero — el riel es fijo, posiciona el banco con precisión.', 'Ρύθμισε πρώτα τη θέση σου — η τροχιά είναι σταθερή, τοποθέτησε τον πάγκο με ακρίβεια.'),
  ('machine incline press', 'Drive through the handles at an upward angle; keep your back against the pad.', 'Empuja los agarres en ángulo ascendente; espalda pegada al respaldo.', 'Πίεσε τις λαβές σε ανοδική γωνία· πλάτη κολλημένη στο μαξιλάρι.'),
  ('svend press', 'Squeeze the plate hard between both palms and press straight out from the chest.', 'Aprieta el disco entre las palmas y empuja recto desde el pecho.', 'Σφίξε δυνατά τον δίσκο ανάμεσα στις παλάμες και πίεσε ευθεία από το στήθος.'),
  -- ── Back ──
  ('deadlift', 'Brace hard, push the floor away, and keep the bar dragging up your legs.', 'Aprieta el core, empuja el suelo y mantén la barra pegada a las piernas.', 'Σφίξε τον κορμό, σπρώξε το πάτωμα και κράτα την μπάρα κολλητά στα πόδια.'),
  ('barbell row', 'Hinge to ~45°, pull the bar to your lower ribs, and squeeze the blades together.', 'Inclina el torso ~45°, lleva la barra a las costillas bajas y junta las escápulas.', 'Κλίση ~45°, τράβα την μπάρα στα κάτω πλευρά και σφίξε τις ωμοπλάτες.'),
  ('pendlay row', 'Reset the bar on the floor each rep; explode it to your chest with a flat back.', 'Apoya la barra en el suelo cada repetición; jálala explosiva al pecho con espalda plana.', 'Ακούμπα την μπάρα στο πάτωμα κάθε φορά· τράβα εκρηκτικά στο στήθος με ίσια πλάτη.'),
  ('dumbbell row', 'Support on the bench, pull the dumbbell to your hip, and avoid torso rotation.', 'Apóyate en el banco, lleva la mancuerna a la cadera y evita rotar el torso.', 'Στήριξη στον πάγκο, τράβα τον αλτήρα στον γοφό χωρίς περιστροφή κορμού.'),
  ('t-bar row', 'Chest up, hinge steady; drive elbows back and squeeze at the top.', 'Pecho arriba, bisagra estable; codos atrás y aprieta arriba.', 'Στήθος ψηλά, σταθερή κλίση· αγκώνες πίσω και σφίξιμο στην κορυφή.'),
  ('chest supported row', 'Let the pad take your weight — pure pull, zero momentum.', 'Deja que el respaldo cargue tu peso — jalón puro, cero impulso.', 'Άφησε το μαξιλάρι να πάρει το βάρος — καθαρό τράβηγμα, μηδέν φόρα.'),
  ('seated cable row', 'Sit tall; pull to your navel and let the shoulders roll forward on the stretch.', 'Siéntate erguido; jala al ombligo y deja estirar los hombros al frente.', 'Κάτσε όρθια· τράβα προς τον αφαλό και άφησε διάταση στην επιστροφή.'),
  ('cable row', 'Neutral spine; drive the elbows past the torso and control the return.', 'Columna neutra; lleva los codos detrás del torso y controla la vuelta.', 'Ουδέτερη σπονδυλική στήλη· αγκώνες πίσω από τον κορμό, ελεγχόμενη επιστροφή.'),
  ('lat pulldown', 'Pull the bar to your collarbone with elbows down-and-back; no leaning way back.', 'Lleva la barra a la clavícula con codos abajo y atrás; no te recuestes.', 'Τράβα την μπάρα στην κλείδα με αγκώνες κάτω-πίσω· μην γέρνεις πολύ πίσω.'),
  ('machine lat pulldown (close grip)', 'Elbows tight to the ribs; pull low and pause before the slow release.', 'Codos pegados a las costillas; jala bajo y pausa antes de soltar lento.', 'Αγκώνες κοντά στα πλευρά· τράβα χαμηλά, παύση και αργή επιστροφή.'),
  ('straight-arm pulldown', 'Arms near-straight; sweep the bar to your thighs using only the lats.', 'Brazos casi rectos; lleva la barra a los muslos usando solo dorsales.', 'Χέρια σχεδόν τεντωμένα· φέρε την μπάρα στους μηρούς μόνο με τους πλατείς.'),
  ('pull-up', 'Start from a dead hang; drive elbows to your ribs until chin clears the bar.', 'Desde colgado total; lleva codos a las costillas hasta pasar la barbilla.', 'Από πλήρη ανάρτηση· αγκώνες προς τα πλευρά μέχρι το πηγούνι να περάσει την μπάρα.'),
  ('pull-ups', 'Full hang to chin-over-bar; keep the core braced to stop swinging.', 'De colgado completo a barbilla sobre barra; core firme para no balancear.', 'Πλήρης ανάρτηση μέχρι πηγούνι πάνω από μπάρα· σφιχτός κορμός, όχι αιώρηση.'),
  ('wide-grip pull-up', 'Hands well outside shoulders; lead with the chest and pull elbows wide.', 'Manos bien afuera de los hombros; sube el pecho y codos amplios.', 'Χέρια αρκετά έξω από τους ώμους· οδήγησε με το στήθος, αγκώνες ανοιχτοί.'),
  ('chin-ups', 'Underhand grip; pull until chin clears the bar and lower with control.', 'Agarre supino; sube hasta pasar la barbilla y baja controlado.', 'Ανάποδη λαβή· ανέβα μέχρι το πηγούνι να περάσει και κατέβα ελεγχόμενα.'),
  ('rack pulls', 'Set the pins near knee height; brace and lock out with glutes, not lower back.', 'Barra a la altura de rodillas; aprieta y bloquea con glúteos, no con lumbar.', 'Μπάρα στο ύψος των γονάτων· κλείδωσε με γλουτούς, όχι με τη μέση.'),
  ('face pulls', 'Pull the rope to your forehead with elbows high; finish with hands apart.', 'Lleva la cuerda a la frente con codos altos; termina con manos separadas.', 'Τράβα το σχοινί προς το μέτωπο με ψηλούς αγκώνες· τελείωσε με χέρια ανοιχτά.'),
  ('meadows row', 'Stand beside the landmine; row the sleeve to your hip with a wide elbow.', 'De pie junto al landmine; rema hacia la cadera con codo amplio.', 'Στάσου πλάι στο landmine· κωπηλάτησε προς τον γοφό με ανοιχτό αγκώνα.'),
  ('inverted row', 'Body rigid under the bar; pull your chest to it and pause briefly.', 'Cuerpo rígido bajo la barra; lleva el pecho a la barra y pausa.', 'Σώμα άκαμπτο κάτω από την μπάρα· φέρε το στήθος στην μπάρα με μικρή παύση.'),
  ('snatch-grip deadlift', 'Very wide grip, hips lower than a normal pull; keep the bar close all the way.', 'Agarre muy amplio, caderas más bajas; barra pegada todo el recorrido.', 'Πολύ φαρδιά λαβή, γοφοί χαμηλότερα· μπάρα κοντά σε όλη τη διαδρομή.'),
  ('single-arm lat pulldown', 'Pull one handle to your shoulder; feel the lat, not the biceps, do the work.', 'Jala un agarre al hombro; que trabaje el dorsal, no el bíceps.', 'Τράβα μία λαβή στον ώμο· δούλεψε με τον πλατύ, όχι με τον δικέφαλο.'),
  -- ── Shoulders ──
  ('overhead press', 'Squeeze glutes, brace, and press the bar in a straight line past your face.', 'Aprieta glúteos, core firme, y empuja la barra en línea recta pasando la cara.', 'Σφίξε γλουτούς και κορμό· πίεσε την μπάρα σε ευθεία περνώντας το πρόσωπο.'),
  ('dumbbell shoulder press', 'Start at ear level; press up without flaring the ribs.', 'Empieza a la altura de las orejas; empuja sin abrir las costillas.', 'Ξεκίνα στο ύψος των αυτιών· πίεσε ψηλά χωρίς να ανοίγουν τα πλευρά.'),
  ('arnold press', 'Rotate palms from facing you to facing forward as you press.', 'Gira las palmas de mirarte a mirar al frente mientras empujas.', 'Περίστρεψε τις παλάμες από μέσα προς τα εμπρός καθώς πιέζεις.'),
  ('machine shoulder press', 'Adjust the seat so handles start at ear height; press without shrugging.', 'Asiento ajustado con agarres a la altura de orejas; empuja sin encoger hombros.', 'Ρύθμισε το κάθισμα με λαβές στο ύψος των αυτιών· πίεσε χωρίς σήκωμα ώμων.'),
  ('behind-the-neck press', 'Only with good shoulder mobility: lower just to ear level and press strictly.', 'Solo con buena movilidad: baja hasta las orejas y empuja estricto.', 'Μόνο με καλή κινητικότητα: κατέβασε ως τα αυτιά και πίεσε αυστηρά.'),
  ('lateral raise', 'Lead with the elbows out to the sides; stop at shoulder height, pinkies slightly up.', 'Guía con los codos hacia los lados; para a la altura del hombro.', 'Οδήγησε με τους αγκώνες στο πλάι· σταμάτα στο ύψος του ώμου.'),
  ('lateral raises', 'Slight forward lean, raise to shoulder height, and lower twice as slow.', 'Ligera inclinación, sube a la altura del hombro y baja el doble de lento.', 'Ελαφριά κλίση μπροστά, άνοδος ως τον ώμο, κάθοδος διπλά αργή.'),
  ('cable lateral raise', 'Stand side-on to the stack; raise across your body to shoulder height.', 'De lado a la polea; eleva cruzando el cuerpo hasta el hombro.', 'Πλάγια στην τροχαλία· ανέβασε διαγώνια ως το ύψος του ώμου.'),
  ('front raises', 'Raise to eye level with a neutral or overhand grip; no torso swing.', 'Eleva a la altura de los ojos; sin balancear el torso.', 'Ανέβασε ως το ύψος των ματιών· χωρίς ταλάντευση κορμού.'),
  ('plate front raise', 'Hold the plate at 3 and 9 o''clock; raise to eye level and control down.', 'Sujeta el disco a las 3 y las 9; eleva a los ojos y baja controlado.', 'Κράτα τον δίσκο στις 3 και 9· ανέβασε ως τα μάτια και κατέβασε ελεγχόμενα.'),
  ('rear delt flyes', 'Hinge forward; open the arms wide with soft elbows and squeeze the rear delts.', 'Inclínate; abre los brazos con codos suaves y aprieta el deltoides posterior.', 'Κλίση μπροστά· άνοιξε τα χέρια με μαλακούς αγκώνες, σφίξε τους οπίσθιους δελτοειδείς.'),
  ('reverse pec deck', 'Chest against the pad; sweep the handles back until arms line up with shoulders.', 'Pecho al respaldo; lleva los agarres atrás hasta alinear brazos con hombros.', 'Στήθος στο μαξιλάρι· φέρε τις λαβές πίσω μέχρι ευθυγράμμιση με τους ώμους.'),
  ('cable y-raise', 'Raise the cables up and out into a Y; keep traps relaxed.', 'Eleva los cables arriba y afuera en Y; trapecios relajados.', 'Ανέβασε τα καλώδια ψηλά και έξω σε σχήμα Υ· χαλαροί τραπεζοειδείς.'),
  ('face pull', 'Rope to the bridge of your nose, elbows high, and rotate thumbs back.', 'Cuerda al puente de la nariz, codos altos, pulgares rotando atrás.', 'Σχοινί προς τη μύτη, αγκώνες ψηλά, αντίχειρες να γυρνούν πίσω.'),
  ('cable face pull', 'Set the pulley at face height; pull apart, not just back.', 'Polea a la altura de la cara; separa las manos, no solo jales atrás.', 'Τροχαλία στο ύψος του προσώπου· άνοιξε τα χέρια, όχι μόνο τράβηγμα πίσω.'),
  ('upright row', 'Pull the bar to chest height with elbows leading; stop if shoulders pinch.', 'Sube la barra al pecho con codos guiando; detente si molesta el hombro.', 'Ανέβασε την μπάρα ως το στήθος με τους αγκώνες μπροστά· σταμάτα αν τσιμπάει ο ώμος.'),
  ('shrugs', 'Straight up and down — no rolling; pause a second at the top.', 'Sube y baja recto — sin rotar; pausa un segundo arriba.', 'Ευθεία πάνω-κάτω — χωρίς κύλισμα· παύση ενός δευτερολέπτου ψηλά.'),
  ('dumbbell shrug', 'Dumbbells at your sides; shrug straight up, hold, and lower slowly.', 'Mancuernas a los lados; encoge recto, sostén y baja lento.', 'Αλτήρες στα πλάγια· ανασήκωσε ευθεία, κράτησε και κατέβασε αργά.'),
  -- ── Biceps ──
  ('barbell curl', 'Elbows pinned to your sides; curl without leaning back.', 'Codos fijos al costado; curl sin inclinarte atrás.', 'Αγκώνες σταθεροί στα πλευρά· κάμψη χωρίς κλίση πίσω.'),
  ('ez-bar curl', 'The angled grip spares the wrists; keep elbows still and squeeze at the top.', 'El agarre angulado cuida las muñecas; codos quietos y aprieta arriba.', 'Η γωνιακή λαβή προστατεύει τους καρπούς· αγκώνες ακίνητοι, σφίξιμο ψηλά.'),
  ('dumbbell curl', 'Supinate as you curl — pinky up at the top — and lower slow.', 'Supina al subir — meñique arriba al final — y baja lento.', 'Γύρνα την παλάμη καθώς ανεβαίνεις και κατέβασε αργά.'),
  ('hammer curl', 'Neutral grip throughout; drive up without swinging the elbows forward.', 'Agarre neutro; sube sin llevar los codos adelante.', 'Ουδέτερη λαβή· ανέβασε χωρίς οι αγκώνες να πάνε μπροστά.'),
  ('cable rope hammer curl', 'Neutral rope grip; curl high and keep constant cable tension.', 'Agarre neutro en cuerda; sube alto con tensión constante.', 'Ουδέτερη λαβή στο σχοινί· κάμψη ψηλά με σταθερή τάση.'),
  ('incline curl', 'Lie back on the incline; let the arms hang behind you for a long stretch.', 'Recuéstate en el banco inclinado; deja colgar los brazos atrás para más estiramiento.', 'Ξάπλωσε στον επικλινή· άφησε τα χέρια πίσω για μεγάλη διάταση.'),
  ('preacher curl', 'Armpits tight over the pad; never bounce out of the stretched bottom.', 'Axilas firmes sobre el apoyo; nunca rebotes desde abajo.', 'Μασχάλες σταθερές στο μαξιλάρι· ποτέ αναπήδηση από την τεντωμένη θέση.'),
  ('spider curl', 'Chest on the incline pad, arms hanging vertical; curl strictly.', 'Pecho en el banco inclinado, brazos verticales; curl estricto.', 'Στήθος στον πάγκο, χέρια κάθετα· αυστηρή κάμψη.'),
  ('concentration curl', 'Elbow braced inside the thigh; curl slow and squeeze hard at the top.', 'Codo apoyado en el muslo; sube lento y aprieta fuerte arriba.', 'Αγκώνας στο εσωτερικό του μηρού· αργή κάμψη, δυνατό σφίξιμο ψηλά.'),
  ('cable curl', 'Constant tension is the point — control both directions fully.', 'La tensión constante es la clave — controla ambas direcciones.', 'Το ζητούμενο είναι η σταθερή τάση — έλεγχος και στις δύο κατευθύνσεις.'),
  ('bayesian cable curl', 'Face away from the stack with the arm behind you; curl through the long stretch.', 'De espaldas a la polea con el brazo atrás; curl desde el estiramiento largo.', 'Πλάτη στην τροχαλία με το χέρι πίσω· κάμψη μέσα από τη μεγάλη διάταση.'),
  ('zottman curl', 'Curl palms-up, rotate palms-down at the top, and lower slowly.', 'Sube en supino, gira a prono arriba y baja lento.', 'Ανέβα με παλάμες πάνω, γύρνα ανάποδα ψηλά και κατέβα αργά.'),
  -- ── Triceps ──
  ('close-grip bench press', 'Hands just inside shoulder width; tuck the elbows and press through the triceps.', 'Manos algo más cerradas que los hombros; codos pegados y empuja con tríceps.', 'Χέρια λίγο πιο κλειστά από τους ώμους· αγκώνες κοντά, πίεση με τρικέφαλα.'),
  ('jm press', 'Hybrid of press and extension: lower the bar toward your chin, elbows forward.', 'Híbrido de press y extensión: baja la barra hacia la barbilla con codos al frente.', 'Υβρίδιο πίεσης και έκτασης: κατέβασε προς το πηγούνι με αγκώνες μπροστά.'),
  ('skull crusher', 'Lower the bar to your forehead with still elbows; extend without flaring.', 'Baja la barra a la frente con codos quietos; extiende sin abrirlos.', 'Κατέβασε την μπάρα στο μέτωπο με ακίνητους αγκώνες· έκταση χωρίς άνοιγμα.'),
  ('skull crushers', 'Elbows fixed and slightly back; stretch behind the head, extend to lockout.', 'Codos fijos y algo atrás; estira tras la cabeza y extiende al bloqueo.', 'Αγκώνες σταθεροί, ελαφρώς πίσω· διάταση πίσω από το κεφάλι, πλήρης έκταση.'),
  ('overhead tricep extension', 'Elbows by your ears; lower behind the head and extend fully.', 'Codos junto a las orejas; baja tras la cabeza y extiende del todo.', 'Αγκώνες δίπλα στα αυτιά· κατέβασε πίσω από το κεφάλι και τέντωσε πλήρως.'),
  ('overhead cable extension', 'Face away from the stack; extend overhead and squeeze at lockout.', 'De espaldas a la polea; extiende sobre la cabeza y aprieta al final.', 'Πλάτη στην τροχαλία· έκταση πάνω από το κεφάλι με σφίξιμο στο τέλος.'),
  ('tricep pushdown', 'Pin the elbows to your sides; push to full lockout and control up.', 'Codos fijos al costado; empuja hasta bloquear y controla la subida.', 'Αγκώνες σταθεροί στα πλευρά· πίεση ως το κλείδωμα, ελεγχόμενη επιστροφή.'),
  ('rope pushdown', 'Split the rope apart at the bottom; keep shoulders down the whole set.', 'Separa la cuerda abajo; hombros abajo toda la serie.', 'Άνοιξε το σχοινί χαμηλά· ώμοι κάτω σε όλο το σετ.'),
  ('cable tricep kickback', 'Hinge forward, upper arm parallel to the floor; extend straight back.', 'Inclínate, brazo paralelo al suelo; extiende recto atrás.', 'Κλίση μπροστά, βραχίονας παράλληλος στο πάτωμα· έκταση ευθεία πίσω.'),
  ('dumbbell kickback', 'Lock the upper arm level with your torso; only the forearm moves.', 'Fija el brazo al nivel del torso; solo se mueve el antebrazo.', 'Κλείδωσε τον βραχίονα στο επίπεδο του κορμού· κινείται μόνο το αντιβράχιο.'),
  ('tricep dips', 'Stay upright for triceps; lower to 90° elbows and press to lockout.', 'Mantente vertical para tríceps; baja a 90° y empuja hasta bloquear.', 'Κατακόρυφος για τρικέφαλα· κατέβα στις 90° και πίεσε ως το κλείδωμα.'),
  ('bench dip', 'Hands on the bench behind you, hips close; lower to 90° and press up.', 'Manos en el banco atrás, caderas cerca; baja a 90° y sube.', 'Χέρια στον πάγκο πίσω σου, γοφοί κοντά· κατέβα στις 90° και ανέβα.'),
  ('diamond push-ups', 'Hands form a diamond under the chest; elbows track back, not out.', 'Manos en diamante bajo el pecho; codos hacia atrás, no afuera.', 'Χέρια σε ρόμβο κάτω από το στήθος· αγκώνες πίσω, όχι έξω.'),
  -- ── Forearms ──
  ('wrist curl', 'Forearms on the bench, palms up; curl the wrist through a full range.', 'Antebrazos en el banco, palmas arriba; curl de muñeca en rango completo.', 'Αντιβράχια στον πάγκο, παλάμες πάνω· κάμψη καρπού σε πλήρες εύρος.'),
  ('reverse wrist curl', 'Palms down; lift the knuckles up slowly — light weight, strict form.', 'Palmas abajo; sube los nudillos lento — poco peso, forma estricta.', 'Παλάμες κάτω· ανέβασε αργά — ελαφρύ βάρος, αυστηρή τεχνική.'),
  ('reverse barbell curl', 'Overhand grip; curl with still elbows to build forearms and brachialis.', 'Agarre prono; curl con codos quietos para antebrazo y braquial.', 'Λαβή από πάνω· κάμψη με ακίνητους αγκώνες για αντιβράχια.'),
  ('farmer walk', 'Heavy in both hands; walk tall with tight abs and level shoulders.', 'Peso en ambas manos; camina erguido con abdomen firme y hombros nivelados.', 'Βάρος και στα δύο χέρια· περπάτα όρθια με σφιχτούς κοιλιακούς.'),
  ('wrist roller', 'Arms out front; roll the weight up and down without dropping the elbows.', 'Brazos al frente; enrolla el peso arriba y abajo sin bajar los codos.', 'Χέρια μπροστά· τύλιξε το βάρος πάνω-κάτω χωρίς να πέφτουν οι αγκώνες.'),
  ('plate pinch', 'Pinch smooth plates together fingertips-to-thumb; hold for time.', 'Sujeta discos lisos entre dedos y pulgar; aguanta por tiempo.', 'Κράτα λείους δίσκους με δάχτυλα-αντίχειρα· κράτημα με χρόνο.'),
  -- ── Quads ──
  ('squat', 'Brace, sit between your hips, and drive up through the mid-foot.', 'Aprieta el core, siéntate entre las caderas y empuja desde el mediopié.', 'Σφίξε τον κορμό, κάτσε ανάμεσα στους γοφούς και πίεσε από το μέσο πέλμα.'),
  ('barbell squat', 'Big breath at the top; knees track over toes; hit depth and drive up.', 'Respira arriba; rodillas sobre los dedos; llega a profundidad y sube.', 'Βαθιά ανάσα ψηλά· γόνατα πάνω από δάχτυλα· βάθος και δυνατή άνοδος.'),
  ('front squat', 'Elbows high to keep the bar racked; stay upright into the hole.', 'Codos altos para sostener la barra; mantente erguido al bajar.', 'Αγκώνες ψηλά για την μπάρα· μείνε όρθια σε όλο το βάθος.'),
  ('goblet squat', 'Hold the dumbbell at your chest; elbows slide inside the knees at depth.', 'Mancuerna al pecho; codos dentro de las rodillas al fondo.', 'Αλτήρας στο στήθος· αγκώνες μέσα από τα γόνατα στο βάθος.'),
  ('hack squat', 'Back flat on the pad; lower deep and push through the whole foot.', 'Espalda plana al respaldo; baja profundo y empuja con todo el pie.', 'Πλάτη στο μαξιλάρι· βαθύ κάθισμα, πίεση με όλο το πέλμα.'),
  ('pendulum squat', 'Follow the arc down as deep as mobility allows; smooth drive up.', 'Sigue el arco hacia abajo tan profundo como puedas; sube suave.', 'Ακολούθησε το τόξο όσο βαθιά μπορείς· ομαλή άνοδος.'),
  ('belt squat', 'Load hangs from the hips — squat deep with zero spinal load.', 'La carga cuelga de la cadera — sentadilla profunda sin carga espinal.', 'Το βάρος κρέμεται από τους γοφούς — βαθύ κάθισμα χωρίς φόρτιση σπονδυλικής.'),
  ('smith machine squat', 'Feet slightly forward of the bar; the fixed path lets you sit back safely.', 'Pies algo adelante de la barra; el riel fijo permite sentarte atrás seguro.', 'Πόδια λίγο μπροστά από την μπάρα· η σταθερή τροχιά επιτρέπει ασφαλές κάθισμα.'),
  ('landmine squat', 'Hold the sleeve at your chest; squat and press slightly forward as you rise.', 'Sujeta el extremo al pecho; baja y empuja algo adelante al subir.', 'Κράτα το άκρο στο στήθος· κάθισμα και ελαφριά πίεση μπροστά στην άνοδο.'),
  ('sissy squat', 'Rise on your toes, lean back, and bend the knees forward — quads only.', 'De puntas, inclínate atrás y dobla rodillas adelante — solo cuádriceps.', 'Στις μύτες, γείρε πίσω και λύγισε τα γόνατα μπροστά — μόνο τετρακέφαλα.'),
  ('leg press', 'Feet mid-platform; lower until hips begin to tuck, never slam the lockout.', 'Pies al centro; baja hasta que la cadera empiece a curvarse, sin golpear el bloqueo.', 'Πέλματα στο κέντρο· κατέβα μέχρι να κυρτώνει η λεκάνη, ποτέ απότομο κλείδωμα.'),
  ('leg press (single leg)', 'One foot centered; press evenly through heel and forefoot.', 'Un pie centrado; empuja parejo con talón y antepié.', 'Ένα πόδι στο κέντρο· πίεση ομοιόμορφα με φτέρνα και μπροστινό πέλμα.'),
  ('leg extension', 'Pause one second at full extension; lower under control.', 'Pausa un segundo en extensión completa; baja controlado.', 'Παύση ενός δευτερολέπτου σε πλήρη έκταση· ελεγχόμενη κάθοδος.'),
  ('lunge', 'Long step, torso tall; both knees to 90° and push back through the front heel.', 'Paso largo, torso erguido; ambas rodillas a 90° y empuja con el talón.', 'Μεγάλο βήμα, όρθιος κορμός· γόνατα στις 90°, ώθηση από τη φτέρνα.'),
  ('lunges', 'Alternate legs; keep the front knee over the ankle, not past the toes.', 'Alterna piernas; rodilla frontal sobre el tobillo, no pasa los dedos.', 'Εναλλάξ πόδια· μπροστινό γόνατο πάνω από τον αστράγαλο.'),
  ('walking lunge', 'Step through continuously; drive off the front heel each stride.', 'Avanza continuo; impúlsate con el talón delantero en cada paso.', 'Συνεχόμενα βήματα· ώθηση από τη μπροστινή φτέρνα σε κάθε διασκελισμό.'),
  ('reverse lunge', 'Step backward — easier on the knees; load stays on the front leg.', 'Paso atrás — más amable con las rodillas; la carga queda en la pierna delantera.', 'Βήμα πίσω — πιο φιλικό στα γόνατα· το φορτίο μένει στο μπροστινό πόδι.'),
  ('bulgarian split squat', 'Rear foot elevated; drop the back knee straight down, torso slightly forward.', 'Pie trasero elevado; baja la rodilla trasera recta, torso algo adelante.', 'Πίσω πόδι ανυψωμένο· κατέβασε το πίσω γόνατο κάθετα, κορμός ελαφρώς μπροστά.'),
  ('step-ups', 'Whole foot on the box; drive up without pushing off the back leg.', 'Pie completo en el cajón; sube sin impulsarte con la pierna trasera.', 'Όλο το πέλμα στο κουτί· ανέβα χωρίς ώθηση από το πίσω πόδι.'),
  ('box jump', 'Land soft and quiet in a quarter squat; step down, don''t jump down.', 'Aterriza suave en cuarto de sentadilla; baja caminando, no saltando.', 'Προσγειώσου μαλακά σε ημικάθισμα· κατέβα περπατώντας, όχι με άλμα.'),
  -- ── Hamstrings ──
  ('romanian deadlift', 'Soft knees; push the hips back until the hamstrings load, then stand tall.', 'Rodillas suaves; lleva la cadera atrás hasta cargar isquios y vuelve erguido.', 'Μαλακά γόνατα· γοφοί πίσω μέχρι να φορτώσουν οι μηριαίοι, μετά όρθια.'),
  ('stiff-leg deadlift', 'Keep the knees nearly straight; hinge deep and keep the bar close.', 'Rodillas casi rectas; bisagra profunda con la barra pegada.', 'Γόνατα σχεδόν τεντωμένα· βαθιά κλίση με την μπάρα κοντά.'),
  ('single-leg deadlift', 'Hinge on one leg with square hips; reach long and stand with control.', 'Bisagra a una pierna con caderas cuadradas; alcanza lejos y sube con control.', 'Κλίση στο ένα πόδι με ίσιους γοφούς· τεντώσου και ανέβα ελεγχόμενα.'),
  ('sumo deadlift', 'Wide stance, toes out; spread the floor and keep the chest proud.', 'Postura amplia, puntas afuera; separa el suelo y pecho arriba.', 'Φαρδιά στάση, δάχτυλα έξω· άνοιξε το πάτωμα με στήθος ψηλά.'),
  ('good morning', 'Bar on the back, soft knees; hinge until the torso nears parallel.', 'Barra a la espalda, rodillas suaves; bisagra hasta casi paralelo.', 'Μπάρα στην πλάτη, μαλακά γόνατα· κλίση μέχρι σχεδόν παράλληλα.'),
  ('leg curl', 'Curl the heels to your glutes; pause, then resist the way back.', 'Lleva talones a los glúteos; pausa y resiste el regreso.', 'Φέρε τις φτέρνες στους γλουτούς· παύση και αντίσταση στην επιστροφή.'),
  ('seated leg curl', 'Thighs pinned under the pad; curl deep under the seat and control up.', 'Muslos fijos bajo el apoyo; curl profundo bajo el asiento y controla.', 'Μηροί σταθεροί κάτω από το μαξιλάρι· βαθιά κάμψη και έλεγχος στην άνοδο.'),
  ('nordic curl', 'Anchor the ankles; lower the body as slowly as possible, hips extended.', 'Ancla los tobillos; baja el cuerpo lo más lento posible con cadera extendida.', 'Σταθεροποίησε αστραγάλους· κατέβα όσο πιο αργά γίνεται με τεντωμένους γοφούς.'),
  ('cable pull-through', 'Face away, rope between the legs; hinge and snap the hips forward.', 'De espaldas, cuerda entre piernas; bisagra y extiende la cadera con fuerza.', 'Πλάτη στην τροχαλία, σχοινί ανάμεσα στα πόδια· κλίση και δυνατή έκταση γοφών.'),
  -- ── Glutes ──
  ('hip thrust', 'Upper back on the bench; drive the hips to full lockout and squeeze.', 'Espalda alta en el banco; extiende la cadera al bloqueo y aprieta.', 'Άνω πλάτη στον πάγκο· ανέβασε τους γοφούς σε πλήρες κλείδωμα και σφίξε.'),
  ('single-leg hip thrust', 'One foot planted; drive to lockout keeping the pelvis level.', 'Un pie apoyado; sube al bloqueo con la pelvis nivelada.', 'Ένα πόδι στο έδαφος· άνοδος σε κλείδωμα με ίσια λεκάνη.'),
  ('glute bridge', 'Heels close to the glutes; lift the hips and hold the squeeze two seconds.', 'Talones cerca de glúteos; eleva la cadera y aprieta dos segundos.', 'Φτέρνες κοντά στους γλουτούς· ανέβασε τη λεκάνη και σφίξε δύο δευτερόλεπτα.'),
  ('cable kickback', 'Hinge slightly; kick straight back through the heel without arching the back.', 'Inclínate un poco; patea recto atrás con el talón sin arquear la espalda.', 'Ελαφριά κλίση· κλωτσιά ευθεία πίσω από τη φτέρνα χωρίς κύρτωμα μέσης.'),
  ('curtsy lunge', 'Step back and across behind the front leg; keep hips facing forward.', 'Paso atrás y cruzado tras la pierna delantera; caderas al frente.', 'Βήμα πίσω και διαγώνια πίσω από το μπροστινό πόδι· γοφοί μπροστά.'),
  ('frog pump', 'Soles of the feet together, knees wide; pump the hips up and squeeze.', 'Plantas juntas, rodillas abiertas; eleva la cadera y aprieta.', 'Πέλματα ενωμένα, γόνατα ανοιχτά· ανέβασε τη λεκάνη και σφίξε.'),
  ('hip abduction machine', 'Sit tall; push the knees apart slowly and resist the return fully.', 'Siéntate erguido; abre las rodillas lento y resiste el regreso.', 'Κάτσε όρθια· άνοιξε τα γόνατα αργά και αντιστάσου πλήρως στην επιστροφή.'),
  -- ── Calves ──
  ('calf raise', 'Full stretch at the bottom, big squeeze at the top — no bouncing.', 'Estiramiento completo abajo, contracción arriba — sin rebotar.', 'Πλήρης διάταση κάτω, δυνατό σφίξιμο πάνω — χωρίς αναπηδήσεις.'),
  ('calf raises', 'Pause one second at the top and stretch fully at the bottom.', 'Pausa un segundo arriba y estira del todo abajo.', 'Παύση ενός δευτερολέπτου πάνω και πλήρης διάταση κάτω.'),
  ('seated calf raise', 'Knees bent targets the soleus; slow reps through a full range.', 'Con rodillas dobladas trabaja el sóleo; repeticiones lentas y completas.', 'Με λυγισμένα γόνατα δουλεύει ο υποκνημίδιος· αργές πλήρεις επαναλήψεις.'),
  ('standing calf raise machine', 'Shoulders under the pads; rise as high as possible, stretch deep at the bottom.', 'Hombros bajo las almohadillas; sube al máximo y estira profundo abajo.', 'Ώμοι κάτω από τα μαξιλάρια· ανέβα όσο ψηλά γίνεται, βαθιά διάταση κάτω.'),
  ('leg press calf raise', 'Balls of the feet on the platform edge; press through a full ankle range.', 'Antepié al borde de la plataforma; empuja en rango completo de tobillo.', 'Μύτες στο άκρο της πλατφόρμας· πίεση σε πλήρες εύρος αστραγάλου.'),
  ('donkey calf raise', 'Hinge forward with support; the stretch at the bottom is the point.', 'Inclínate con apoyo; el estiramiento abajo es la clave.', 'Κλίση μπροστά με στήριξη· η διάταση κάτω είναι το ζητούμενο.'),
  -- ── Core ──
  ('plank', 'Squeeze glutes and abs; one straight line from head to heels.', 'Aprieta glúteos y abdomen; línea recta de cabeza a talones.', 'Σφίξε γλουτούς και κοιλιακούς· ευθεία γραμμή από κεφάλι ως φτέρνες.'),
  ('side plank', 'Stack the feet, lift the hips high, and keep the shoulder over the elbow.', 'Pies apilados, cadera alta y hombro sobre el codo.', 'Πόδια σε ευθεία, γοφοί ψηλά, ώμος πάνω από τον αγκώνα.'),
  ('crunches', 'Curl the ribs toward the pelvis; don''t pull on your neck.', 'Encoge costillas hacia la pelvis; no jales el cuello.', 'Φέρε τα πλευρά προς τη λεκάνη· μην τραβάς τον αυχένα.'),
  ('bicycle crunches', 'Slow opposite elbow-to-knee; keep the lower back gently pressed down.', 'Codo a rodilla contraria lento; lumbar apoyada suave.', 'Αργά αντίθετος αγκώνας-γόνατο· μέση απαλά πιεσμένη κάτω.'),
  ('reverse crunch', 'Curl the pelvis off the floor with control; no leg swinging.', 'Encoge la pelvis del suelo con control; sin balancear piernas.', 'Σήκωσε τη λεκάνη από το πάτωμα ελεγχόμενα· χωρίς αιώρηση ποδιών.'),
  ('weighted sit-up', 'Hold the plate at your chest; roll up one vertebra at a time.', 'Disco al pecho; sube vértebra por vértebra.', 'Δίσκος στο στήθος· ανέβα σπόνδυλο-σπόνδυλο.'),
  ('cable crunch', 'Kneel, hands by your head; crunch ribs to hips against the stack.', 'De rodillas, manos junto a la cabeza; encoge costillas a caderas contra la polea.', 'Γονατιστή, χέρια στο κεφάλι· δίπλωσε πλευρά προς γοφούς κόντρα στην τροχαλία.'),
  ('hanging leg raise', 'From a dead hang, raise the legs with a posterior pelvic tilt — no swing.', 'Desde colgado, sube las piernas basculando la pelvis — sin balanceo.', 'Από ανάρτηση, ανέβασε τα πόδια με κλίση λεκάνης — χωρίς ταλάντευση.'),
  ('toes-to-bar', 'Lat-pull the bar down as the toes come up; control the negative.', 'Jala la barra con dorsales mientras suben los pies; controla la bajada.', 'Τράβα την μπάρα με τους πλατείς καθώς ανεβαίνουν τα πόδια· έλεγχος στην κάθοδο.'),
  ('hollow hold', 'Press the lower back into the floor; arms and legs long and hovering.', 'Lumbar pegada al suelo; brazos y piernas extendidos y elevados.', 'Μέση κολλημένη στο πάτωμα· χέρια και πόδια τεντωμένα να αιωρούνται.'),
  ('dead bug', 'Opposite arm and leg extend; the lower back never leaves the floor.', 'Extiende brazo y pierna opuestos; la lumbar nunca se despega.', 'Τέντωσε αντίθετο χέρι-πόδι· η μέση δεν φεύγει ποτέ από το πάτωμα.'),
  ('ab wheel', 'Roll out only as far as you can keep the hips tucked; no sagging.', 'Rueda solo hasta donde mantengas la pelvis firme; sin hundir la cadera.', 'Κύλισε μόνο όσο κρατάς τη λεκάνη σταθερή· χωρίς βύθισμα.'),
  ('russian twist', 'Lean back 45°, rotate from the torso — the arms just follow.', 'Reclínate 45°, gira desde el torso — los brazos solo acompañan.', 'Κλίση 45°, στροφή από τον κορμό — τα χέρια απλώς ακολουθούν.'),
  ('cable woodchop', 'Rotate through the hips and torso; arms stay long like a lever.', 'Gira desde cadera y torso; brazos largos como palanca.', 'Στροφή από γοφούς και κορμό· χέρια τεντωμένα σαν μοχλός.'),
  ('pallof press', 'Press the handle straight out and resist the rotation; breathe steadily.', 'Empuja el agarre al frente y resiste la rotación; respira estable.', 'Πίεσε τη λαβή ευθεία μπροστά και αντιστάσου στην περιστροφή.'),
  ('mountain climbers', 'Hips level with shoulders; drive the knees fast without bouncing the hips.', 'Cadera al nivel de hombros; rodillas rápidas sin rebotar la cadera.', 'Γοφοί στο ύψος των ώμων· γρήγορα γόνατα χωρίς αναπήδηση λεκάνης.'),
  ('v-ups', 'Reach hands to feet in one crisp fold; lower both halves with control.', 'Manos a los pies en un pliegue limpio; baja ambas mitades con control.', 'Χέρια προς πόδια σε ένα καθαρό δίπλωμα· ελεγχόμενη κάθοδος.'),
  -- ── Full body ──
  ('kettlebell swing', 'It''s a hip hinge, not a squat — snap the hips and let the bell float.', 'Es bisagra de cadera, no sentadilla — extiende con fuerza y deja flotar la pesa.', 'Είναι κλίση γοφών, όχι κάθισμα — δυνατή έκταση και άφησε το βαράκι να αιωρηθεί.'),
  ('clean and press', 'Explode the bar to the shoulders, reset, then press strictly overhead.', 'Sube explosivo a los hombros, acomoda y empuja estricto arriba.', 'Εκρηκτικά στους ώμους, σταθεροποίηση και αυστηρή πίεση ψηλά.'),
  ('power clean', 'Triple extension — ankles, knees, hips — then catch high on the shoulders.', 'Triple extensión — tobillos, rodillas, cadera — y recibe alto en hombros.', 'Τριπλή έκταση — αστράγαλοι, γόνατα, γοφοί — και υποδοχή ψηλά στους ώμους.'),
  ('thrusters', 'Front squat into an overhead press in one fluid drive.', 'Sentadilla frontal a press de hombros en un solo impulso fluido.', 'Μπροστινό κάθισμα σε πίεση ώμων με μία ρευστή κίνηση.'),
  ('burpees', 'Chest to the floor, snap the hips up, and finish with a small jump.', 'Pecho al suelo, sube la cadera rápido y termina con salto corto.', 'Στήθος στο πάτωμα, γρήγορη άνοδος και μικρό άλμα στο τέλος.'),
  ('turkish get-up', 'Eyes on the bell the whole way; move slow through each position.', 'Mirada en la pesa todo el tiempo; pasa lento por cada posición.', 'Μάτια στο βάρος συνέχεια· αργά από κάθε θέση.'),
  ('man maker', 'Row each arm in the plank, then clean and press to standing.', 'Rema cada brazo en plancha, luego clean y press de pie.', 'Κωπηλατική κάθε χέρι σε σανίδα, μετά clean και πίεση όρθια.'),
  ('devil press', 'A burpee into a double-dumbbell snatch — smooth, not rushed.', 'Burpee a snatch con dos mancuernas — fluido, sin prisa.', 'Burpee σε αρασέ με δύο αλτήρες — ομαλά, όχι βιαστικά.'),
  ('wall ball', 'Deep squat, then drive the ball to the target in one rhythm.', 'Sentadilla profunda y lanza el balón al objetivo en un solo ritmo.', 'Βαθύ κάθισμα και ρίξε την μπάλα στον στόχο με έναν ρυθμό.'),
  ('sled push', 'Low arms, long strides; drive through the whole foot.', 'Brazos bajos, zancadas largas; empuja con todo el pie.', 'Χαμηλά χέρια, μεγάλοι διασκελισμοί· ώθηση με όλο το πέλμα.'),
  ('battle ropes', 'Slight squat, waves from the shoulders; keep breathing rhythmic.', 'Semisentadilla, olas desde los hombros; respiración rítmica.', 'Ημικάθισμα, κύματα από τους ώμους· ρυθμική αναπνοή.'),
  -- ── Cardio ──
  ('treadmill run', 'Relaxed shoulders, quick light steps; land under your hips.', 'Hombros relajados, pasos rápidos y ligeros; aterriza bajo la cadera.', 'Χαλαροί ώμοι, γρήγορα ελαφριά βήματα· προσγείωση κάτω από τους γοφούς.'),
  ('cycling', 'Set saddle height so the knee stays slightly bent at the bottom.', 'Ajusta el sillín para que la rodilla quede algo flexionada abajo.', 'Ρύθμισε τη σέλα ώστε το γόνατο να μένει ελαφρώς λυγισμένο κάτω.'),
  ('rowing machine', 'Legs, then back, then arms — reverse the order on the way in.', 'Piernas, espalda, brazos — invierte el orden al volver.', 'Πόδια, μετά πλάτη, μετά χέρια — αντίστροφα στην επιστροφή.'),
  ('swimming', 'Long strokes, steady exhale in the water; keep the hips high.', 'Brazadas largas, exhala constante en el agua; cadera alta.', 'Μεγάλες χεριές, σταθερή εκπνοή στο νερό· γοφοί ψηλά.'),
  ('jump rope', 'Bounce on the balls of the feet; spin from the wrists, not the arms.', 'Rebota en el antepié; gira desde las muñecas, no los brazos.', 'Αναπήδηση στις μύτες· περιστροφή από τους καρπούς, όχι τα χέρια.'),
  ('elliptical', 'Push and pull the handles; keep the heels down for glute drive.', 'Empuja y jala los agarres; talones abajo para activar glúteos.', 'Σπρώξε και τράβα τις λαβές· φτέρνες κάτω για γλουτούς.'),
  ('stair climber', 'Stand tall, fingertips only on the rails; step through the whole foot.', 'Erguido, solo puntas de dedos en el pasamanos; pisa con todo el pie.', 'Όρθια, μόνο ακροδάχτυλα στα χερούλια· πάτημα με όλο το πέλμα.'),
  ('assault bike', 'Drive arms and legs together; pace steady, spike for intervals.', 'Impulsa brazos y piernas juntos; ritmo estable, acelera en intervalos.', 'Χέρια και πόδια μαζί· σταθερός ρυθμός, ξεσπάσματα στα διαστήματα.'),
  ('incline walk', 'Steep grade, no rail-holding; lean slightly into the hill.', 'Pendiente alta sin agarrarte; inclínate leve hacia la cuesta.', 'Απότομη κλίση χωρίς κράτημα· ελαφριά κλίση προς τα εμπρός.'),
  ('sprint intervals', 'All-out effort, full recovery between reps; hold form when tired.', 'Esfuerzo máximo, recuperación completa entre series; mantén la técnica al fatigarte.', 'Μέγιστη προσπάθεια, πλήρης αποκατάσταση· κράτα την τεχνική στην κούραση.'),
  ('ski erg', 'Hinge from the hips and drive the handles down in one pull.', 'Bisagra de cadera y lleva los agarres abajo en un solo jalón.', 'Κλίση από τους γοφούς και τράβηγμα των λαβών κάτω με μία κίνηση.'),
  ('sled drag', 'Lean away from the sled; short powerful steps, arms long.', 'Inclínate lejos del trineo; pasos cortos y potentes, brazos extendidos.', 'Γείρε μακριά από το έλκηθρο· κοντά δυνατά βήματα, τεντωμένα χέρια.')
) AS v(name, en, es, el)
WHERE lower(e.name) = v.name AND e.is_template = true;
